cat > s3.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:60694');
await p.fill('input[type=email]','ops@lab.test');
await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');
await p.waitForLoadState('networkidle');
await p.click('text=Expenses');
await p.waitForLoadState('networkidle');
await p.locator('tr[data-id=e9] .ac span').nth(0).click();
await p.waitForTimeout(800);
await p.locator('tr[data-id=e2] .ac span').nth(1).click();
await p.waitForTimeout(800);
await p.reload(); await p.waitForLoadState('networkidle');
console.log(await p.evaluate(()=>[...document.querySelectorAll('tr[data-id]')].map(r=>r.innerText.replace(/\s+/g,' ')).join('\n')));
await b.close();
EOF
